// ---- moveRand(60, 4, 1.0) with moveLimit(0, 128, 280, 64) ----
// moveLimit width/height are full extents: x in [-140,140], y in [96,160].
// The native direction choice uses the inner quarter: x +-70, y 112..144.
// Enemy slots: int0 = next movement step (1..60), fx0/fx1 = logical unit direction.

sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// One direction sample per call; BAM branches mirror the source f32 rules.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;                       // R/3
    } else if $self_x > 70fx {
        a = r / 3 + 32768;               // wrap(R/3 + pi)
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;                       // R/4
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = 0 - a; }
    } else if $self_y > 144fx {
        if a < 0 { a = 0 - a; }
        a = 0 - a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad (nearest BAM boundary +-522).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// ---- MBossCard1_at (:263-327) ----
// Fixed ring, 8 ways x 3 speed layers, base rotates -+10deg per volley.
// H: 8 volleys every 6 frames, layers 1.4/1.2/1.0. L: 10 volleys every 5, 2.0/1.6/1.2.
// etAngle ang2 (+-2deg) is the per-layer rotation. EX ANIM a=1 spawn retreat kept:
// bullet starts 4*speed behind the muzzle along its own angle.
async sub fan_burst(dir: int) {
    var volleys: int = 8;
    var gap: int = 6;
    var v0: fx = 1.4fx;
    var dv: fx = 0fx - 0.2fx;
    if global(GVAR_RANK) >= RANK_LUNATIC {
        volleys = 10;
        gap = 5;
        v0 = 2.0fx;
        dv = 0fx - 0.4fx;
    }
    var layer_step: int = 364 * dir;
    var spin: int = 0 - 1820 * dir;
    var base: int = 0;
    for v in 0..volleys {
        for q in 0..3 {
            var speed: fx = v0 + dv * q;
            for i in 0..8 {
                var a: int = base + (i * 65536) / 8 + q * layer_step;
                var bx: fx = $self_x - 4fx * speed * cos(a as angle);
                var by: fx = $self_y - 4fx * speed * sin(a as angle);
                _ = fire(TH14_SHARD, 6, bx, by, speed, a as angle, none, none);
            }
        }
        base = base + spin;
        wait(gap);
    }
}

// ---- MBossCard1_at2 (:329-413) ----
// 1 way x 6 layers, layers 8.0 -> 1.0 (step -1.4), etAngle ang2 +-3deg.
// EX slot 1 STEP a=60 b=1 c=0: 60 frames of linear decel to 0, then +-90deg and speed 1.5.
// EX slot 0 ANIM a=1 spawn retreat kept (4*speed behind the muzzle).
xformdef OVAL_STOP_TURN_R {
    step_speed(0fx, 60);
    wait(60);
    turn(90deg);
    set_speed(1.5fx);
}
xformdef OVAL_STOP_TURN_L {
    step_speed(0fx, 60);
    wait(60);
    turn(0deg - 90deg);
    set_speed(1.5fx);
}

sub oval_volley(base: int, layer_step: int, turn_right: int) {
    // source %RANDRAD / 32: one +-pi/32 offset shared by the whole volley
    var a0: int = base + (rand(65536) - 32768) / 32;
    for q in 0..6 {
        var speed: fx = 8fx + (0fx - 1.4fx) * q;
        var a: int = a0 + q * layer_step;
        var bx: fx = $self_x - 4fx * speed * cos(a as angle);
        var by: fx = $self_y - 4fx * speed * sin(a as angle);
        if turn_right != 0 {
            _ = fire(TH14_OVAL, 4, bx, by, speed, a as angle, OVAL_STOP_TURN_R, none);
        } else {
            _ = fire(TH14_OVAL, 4, bx, by, speed, a as angle, OVAL_STOP_TURN_L, none);
        }
    }
}

async sub stop_turn_loop() {
    var start_delay: int = 300;   // H 300 / L 150
    var cycle: int = 160;         // H 160 / L 80
    var volleys: int = 2;         // !HL two volleys; L gets the extra !L volley
    if global(GVAR_RANK) >= RANK_LUNATIC {
        start_delay = 150;
        cycle = 80;
        volleys = 3;
    }
    wait(start_delay);
    var c: int = 600;
    while c > 0 {
        // :382-389 three volleys share one frame (22.5deg / 11.25deg !HL / 45deg !L)
        oval_volley(4096, 546, 1);
        if volleys >= 2 { oval_volley(2048, 546, 1); }
        if volleys >= 3 { oval_volley(8192, 546, 1); }
        wait(cycle);
        // :392-399 (157.5deg / 168.75deg !HL / 135deg !L)
        oval_volley(28672, -546, 0);
        if volleys >= 2 { oval_volley(30720, -546, 0); }
        if volleys >= 3 { oval_volley(24576, -546, 0); }
        wait(cycle);
        c = c - 1;
    }
}

// Source timerReset (:225) is the spell start; at 1500 frames MBossDead runs
// spellEnd + etClear(640). No follow-up attack.
async sub card_timeout() {
    wait(OPENING_BUFFER + SOURCE_LIMIT);
    spell_end();
}

async sub card_pattern() {
    spawn card_timeout();
    wait(OPENING_BUFFER);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);   // :241 movePosTime(60, 4, 0, 144)
    wait(60);
    spawn stop_turn_loop();                   // :247 @MBossCard1_at2() async
    var dir: int = 1;
    loop {
        spawn fan_burst(dir);                 // :250 / :254 @MBossCard1_at() async
        dir = 0 - dir;
        card_wait(20);
        card_move_rand();                     // :252 / :256 moveRand(60, 4, 1.0)
        card_wait(80);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(24fx);   // context setHurtbox(48,48) -> radius 24
    set_hitbox(20fx);    // context setHitbox(40,40) -> radius 20
    spell_begin(0, SPELL_ID, card_pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    // MBossDead timeout branch for H/L: etClear(640) without item conversion.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    loop { wait(60); }
}

sub main() {
    // Representative entry position from the shared intro (0,128); hp continues at the
    // inherited 1300 threshold; no leftover bullets. No DPS is simulated.
    _ = spawn_enemy(0fx, 128fx, 1300, 0, 0, 0, boss_main);
    loop { wait(600); }
}
